class Dud < Formula
  desc "Discreet upload / download over dead drops and paired peers"
  homepage "https://github.com/wojciechpolak/dud"
  url "https://github.com/wojciechpolak/dud/archive/refs/tags/v2.1.0.tar.gz"
  sha256 "154597c562a5bd4b09a18a7c02e94eef6f7b4d2ab680fca1c111ed58ac15152a"
  license "MIT"

  depends_on "go" => :build
  depends_on "age"
  depends_on "git"
  depends_on "qrencode"

  def install
    cd "client" do
      ENV["CGO_ENABLED"] = "0"
      ldflags = "-buildid= -X main.version=#{version}"
      system "go", "build", *std_go_args(output: bin/"dud", ldflags: ldflags), "./cmd/dud"
    end
  end

  test do
    assert_equal version.to_s, shell_output("#{bin}/dud --version").strip
  end
end
